import { syncAppBadge, installApp, enableBadge } from './pwa.js';
import { DEFAULT_TEMPLATE, validTemplatePath, loadTemplate } from './static-files.js';
import { cleanRichText, safeLink, googleCalendarUrl, participantsCsv } from './portal-tools.js';
import { api } from './api.js';
import { CERTIFICATE_RELEASE } from './config.js';
import { demoSessions,demoPresenters } from './content.js';
import { badge,certificate,download } from './documents.js';

const $=s=>document.querySelector(s), root=$('#app');
const readPref=(key,fallback)=>{try{return localStorage.getItem(key)||fallback;}catch{return fallback;}};
const state={lang:readPref('pilc-language','en'),theme:readPref('pilc-theme','light'),user:null,profile:null,authReady:false,profileReady:false,authMode:'login',sessions:[],presenters:[],users:[],submissions:[],settings:null,submission:null,day:'18',adminTab:'people',filter:'all',search:'',loading:false,error:'',editSession:null,editPresenter:null,saved:[],notices:[],sentNotices:[],readNotices:[]};
const t=(en,hr)=>state.lang==='hr'?hr:en;
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',check:'<path d="m5 12 4 4L19 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 5 9 8 9-8"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 3H3v18h6m5-14 5 5-5 5M8 12h12"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v6h5M8 13h8M8 17h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>'};
icons.bell='<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>';
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const roleName=r=>({guest:t('Participant','Sudionik'),presenter:t('Presenter','Izlagač'),admin:t('Administrator','Administrator')}[r]||r);
const statusName=s=>({pending:t('Pending approval','Čeka odobrenje'),approved:t('Approved','Odobreno'),rejected:t('Not approved','Nije odobreno'),submitted:t('Submitted','Predano'),accepted:t('Accepted','Prihvaćeno'),revision:t('Revision requested','Potrebna dorada')}[s]||s);
const btn=(text,action,kind='primary',ico='arrow',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${text}${ico?icon(ico):''}</button>`;
const logo=()=>'<span class="brand"><img src="assets/pilc-logo.png" alt="PILC 2027 — PAR International Leadership Conference"></span>';
const approved=()=>!!state.user&&state.profile?.status==='approved';
const admin=()=>approved()&&state.profile?.role==='admin';
const langText=obj=>state.lang==='hr'?obj.titleHr:obj.titleEn;
function localizedLabel(value){const labels={'Opening':'Otvaranje','Keynote':'Uvodno predavanje','Panel':'Panel','Scientific session':'Znanstvena sesija','Workshop':'Radionica','Closing':'Zatvaranje','Main hall':'Glavna dvorana','Conference room':'Konferencijska dvorana'};if(value.includes(' / ')){const parts=value.split(' / ');return state.lang==='hr'?parts[1]:parts[0];}return state.lang==='hr'?(labels[value]||value):value;}
function header(portal=false){return `<header class="site-header"><a class="brand-link" href="${portal?'#home':'#'}" aria-label="PILC 2027">${logo()}</a>${portal?`<nav id="navigation" aria-label="${t('Main navigation','Glavna navigacija')}">${[['home',t('Home','Početna')],['about',t('About','O konferenciji')],['programme',t('Programme','Program')],['my-programme',t('My programme','Moj program')],['papers',t('Paper submission','Predaja radova')],['contact',t('Contact','Kontakt')]].map(([id,title])=>`<a href="#${id}" class="${route()===id?'active':''}" ${route()===id?'aria-current="page"':''}>${title}</a>`).join('')}${admin()?`<a href="#admin" class="${route()==='admin'?'active':''}">Admin</a>`:''}</nav>`:`<span class="header-caption">${t('PARTICIPANT PORTAL','PORTAL ZA SUDIONIKE')}</span>`}<div class="header-tools"><button class="language" data-action="language" aria-label="${t('Switch to Croatian','Switch to English')}">${state.lang==='en'?'EN':'HR'} <span>⌄</span></button><button class="icon-button" data-action="theme" aria-label="${t('Switch colour theme','Promijeni temu')}" title="${t('Light / dark mode','Svijetla / tamna tema')}">${icon(state.theme==='light'?'moon':'sun')}</button>${portal?`<a class="icon-button notices-link" href="#notifications" aria-label="${t('Announcements','Obavijesti')}">${icon('bell')}<span id="notice-count" ${state.notices.every(n=>state.readNotices.includes(n.id))?'hidden':''}>${state.notices.filter(n=>!state.readNotices.includes(n.id)).length}</span></a><a class="avatar" href="#profile" aria-label="${t('My profile','Moj profil')}">${e(initials())}</a><button class="icon-button menu-button" data-action="menu" aria-label="${t('Open navigation','Otvori navigaciju')}" aria-expanded="false">${icon('menu')}</button>`:''}</div></header>`;}
const initials=()=>`${state.profile?.firstName?.[0]||''}${state.profile?.lastName?.[0]||''}`;
const footer=()=>`<footer><span>© 2027 PILC · ${t('PAR University of Applied Sciences','Veleučilište PAR')}</span><div><a href="mailto:conference@par.hr">conference@par.hr</a><a href="#privacy">${t('Privacy','Privatnost')}</a><button class="text-button" data-action="install-app">${t('Install app','Instaliraj aplikaciju')}</button>${state.user?`<button class="text-button" data-action="logout">${t('Sign out','Odjava')}</button>`:''}</div></footer>`;
function field(label,name,value='',opts={}){return `<label class="field ${opts.full?'full':''}"><span>${label}${opts.optional?` <small>${t('(optional)','(neobavezno)')}</small>`:''}</span>${opts.textarea?`<textarea name="${name}" rows="${opts.rows||4}" maxlength="${opts.max||5000}" ${opts.optional?'':'required'}>${e(value)}</textarea>`:`<input name="${name}" type="${opts.type||'text'}" value="${e(value)}" ${opts.optional?'':'required'} maxlength="${opts.max||120}" ${opts.min?`minlength="${opts.min}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${opts.placeholder?`placeholder="${e(opts.placeholder)}"`:''} ${opts.extra||''}>`}</label>`;}
function profileFields(p={}){return `<div class="form-grid">${field(t('First name','Ime'),'firstName',p.firstName,{autocomplete:'given-name',max:60})}${field(t('Last name','Prezime'),'lastName',p.lastName,{autocomplete:'family-name',max:60})}${field(t('Title','Titula'),'title',p.title,{optional:true,placeholder:t('e.g. Dr., Prof.','npr. dr. sc., prof.'),max:60})}${field(t('Affiliation / organisation','Ustanova / organizacija'),'affiliation',p.affiliation,{autocomplete:'organization',max:160})}</div>`;}
function authView(){const mode=state.authMode;return `${header()}<main id="main" class="auth-layout"><section class="auth-form-panel"><div class="auth-form-inner"><span class="eyebrow">${t('PARTICIPANT PORTAL','PORTAL ZA SUDIONIKE')}</span><h2>${mode==='register'?t('Create your account','Izradite račun'):mode==='reset'?t('Reset your password','Obnovite lozinku'):t('Log in to PILC 2027','Prijava na PILC 2027')}</h2><p class="muted">${mode==='register'?t('Create your account. Our team will review your registration before you enter the portal.','Izradite račun. Naš tim pregledat će registraciju prije pristupa portalu.'):mode==='reset'?t('Enter your email and we’ll send you a password reset link.','Unesite e-mail i poslat ćemo poveznicu za novu lozinku.'):t('Access your programme, badge and conference details.','Pristupite programu, akreditaciji i podacima o konferenciji.')}</p>${mode!=='reset'?`<div class="auth-tabs"><button data-action="login-mode" class="${mode==='login'?'selected':''}">${t('Log in','Prijava')}</button><button data-action="register-mode" class="${mode==='register'?'selected':''}">${t('Create an account','Registracija')}</button></div>`:''}<form id="auth-form">${mode==='register'?profileFields():''}${field(t('Email address','E-mail adresa'),'email','',{type:'email',autocomplete:'email',placeholder:'name@organisation.com',max:254})}${mode!=='reset'?`<div class="password-field">${field(t('Password','Lozinka'),'password','',{type:'password',min:mode==='register'?8:0,autocomplete:mode==='register'?'new-password':'current-password',placeholder:mode==='register'?t('At least 8 characters','Najmanje 8 znakova'):'••••••••',max:128})}<button type="button" class="password-toggle icon-button" data-action="password" aria-label="${t('Show password','Prikaži lozinku')}">${icon('eye')}</button></div>`:''}${mode==='register'?`<label class="field"><span>${t('I would like to join as','Želim sudjelovati kao')}</span><select name="requestedRole"><option value="guest">${t('Participant','Sudionik')}</option><option value="presenter">${t('Presenter / paper author','Izlagač / autor rada')}</option></select></label><label class="check-label"><input type="checkbox" required name="privacy"> <span>${t('I have read the','Pročitao/la sam')} <a href="#privacy">${t('privacy information','informacije o privatnosti')}</a>.</span></label>`:mode==='login'?`<div class="form-between"><label class="check-label"><input type="checkbox" name="remember"> ${t('Remember me','Zapamti me')}</label><button type="button" class="text-button" data-action="reset-mode">${t('Forgot password?','Zaboravljena lozinka?')}</button></div>`:''}<p class="form-message" role="alert"></p><button class="btn primary wide" type="submit">${mode==='register'?t('Create account','Izradi račun'):mode==='reset'?t('Send reset link','Pošalji poveznicu'):t('Log in','Prijavi se')}${icon('arrow')}</button></form>${mode==='reset'?btn(t('Back to sign in','Natrag na prijavu'),'login-mode','text',''):''}<div class="auth-help">${icon('mail')}<span>${t('Need a hand?','Trebate pomoć?')} <a href="mailto:conference@par.hr">conference@par.hr</a></span></div><p class="small muted">${t('Organised by PAR University of Applied Sciences.','Organizator: Veleučilište PAR.')}</p></div></section></main>${footer()}`;}
function gateView(){const p=state.profile;return `${header()}<main id="main" class="gate container"><div class="gate-icon">${icon(p?'clock':'user')}</div><span class="eyebrow">PILC 2027</span><h1>${!p?t('Complete your registration','Dovršite registraciju'):p.status==='rejected'?t('Registration not approved.','Registracija nije odobrena.'):t('You’re on the list.','Vaša je prijava zaprimljena.')}</h1><p class="muted">${!p?t('Your account exists. Add your details to send your registration for review.','Račun postoji. Unesite podatke za slanje registracije na pregled.'):p.status==='rejected'?t('Please contact the organising team for more information.','Za više informacija kontaktirajte organizacijski tim.'):t('The organising team is reviewing your registration. Your portal will become available as soon as your account is approved.','Organizacijski tim pregledava vašu prijavu. Portal će biti dostupan čim vaš račun bude odobren.')}</p>${p?`<div class="notice">${e(state.user.email)} · ${statusName(p.status)}</div><div class="button-row">${btn(t('Refresh status','Osvježi status'),'refresh','primary','check')}</div>`:`<form id="complete-form">${profileFields()}<label class="field"><span>${t('Participation','Sudjelovanje')}</span><select name="requestedRole"><option value="guest">${roleName('guest')}</option><option value="presenter">${roleName('presenter')}</option></select></label><p class="form-message" role="alert"></p><button class="btn primary">${t('Submit registration','Pošalji registraciju')}</button></form>`}<a class="contact-link" href="mailto:conference@par.hr">conference@par.hr</a>${btn(t('Sign out','Odjava'),'logout','text','logout')}</main>${footer()}`;}
function pageHeading(kicker,title,description=''){return `<div class="page-heading"><span class="eyebrow">${kicker}</span><h1 tabindex="-1">${title}</h1>${description?`<p class="muted">${description}</p>`:''}</div>`;}
function schedule(compact=false){const rows=(state.sessions.length?state.sessions:demoSessions).filter(s=>s.day===state.day);return `<div class="programme-tabs" role="group" aria-label="${t('Conference day','Dan konferencije')}">${['18','19','20'].map((d,i)=>`<button data-day="${d}" class="${state.day===d?'selected':''}" aria-pressed="${state.day===d}"><span>${t('DAY','DAN')} 0${i+1}</span><strong>${d} ${t('March','ožujka')}</strong></button>`).join('')}</div>${!state.sessions.length?`<p class="demo-note">${t('DEMO PROGRAMME · Illustrative sessions and times, not the confirmed schedule.','DEMO PROGRAM · Ogledne sesije i satnice, nisu potvrđeni raspored.')}</p>`:''}<div class="schedule">${rows.length?rows.slice(0,compact?3:100).map(s=>`<article class="session"><div class="session-time">${e(s.time)}<small>${e(s.end)}</small></div><div><span class="eyebrow">${e(localizedLabel(s.type))}</span><h3>${e(langText(s))}</h3><p>${icon('pin')}${e(localizedLabel(s.room))}</p>${sessionActions(s)}</div></article>`).join(''):`<div class="empty">${t('Programme details will be announced here.','Detalji programa bit će objavljeni ovdje.')}</div>`}</div>`;}
function presenterCards(){return `<div class="presenter-grid">${(state.presenters.length?state.presenters:demoPresenters).map(p=>`<article class="presenter-card"><div class="presenter-photo">${p.photo&&safePhoto(p.photo)?`<img src="${e(p.photo)}" alt="${e(p.name)}" loading="lazy" referrerpolicy="no-referrer">`:icon('user')}<span>${p.name?t('PILC PRESENTER','PILC IZLAGAČ'):t('TO BE ANNOUNCED','USKORO OBJAVA')}</span></div><div class="presenter-copy"><span class="eyebrow">${e(langText(p))}</span><h3>${e(p.name)||t('A new perspective.','Nova perspektiva.')}</h3><p class="muted">${e(state.lang==='hr'?p.bioHr:p.bioEn)}</p></div></article>`).join('')}</div>`;}
function home(){return `<div class="welcome-line"><span>${t('Hello','Pozdrav')}, ${e(state.profile.firstName)} <span class="wave">✦</span></span><a href="#profile">${t('Your participant space','Vaš prostor za sudjelovanje')} ${icon('arrow')}</a></div><section class="home-hero"><div class="hero-copy"><span class="eyebrow light">PILC 2027 · RIJEKA / OPATIJA</span><h1>Where leaders<br>meet <em>future leaders.</em></h1><p>${t('Three days of ideas, connections and new perspectives. Be part of the conversation.','Tri dana ideja, povezivanja i novih perspektiva. Budite dio razgovora.')}</p><a class="btn gold" href="#programme">${t('Explore the programme','Istražite program')}${icon('arrow')}</a></div><div class="hero-venue"><div class="venue-photo" role="img" aria-label="Hilton Rijeka Costabella"></div><div class="venue-label">${icon('pin')}<span>Hilton Rijeka Costabella<br><small>Beach Resort & Spa</small></span></div></div></section><div class="event-strip"><div>${icon('calendar')}<span><small>${t('SAVE THE DATE','ZABILJEŽITE DATUM')}</small><strong>${t('18–20 March 2027','18.–20. ožujka 2027.')}</strong></span></div><div>${icon('pin')}<span><small>${t('MEET US IN','VIDIMO SE U')}</small><strong>Rijeka / Opatija, ${t('Croatia','Hrvatska')}</strong></span></div><div>${icon('user')}<span><small>${t('YOUR REGISTRATION','VAŠA REGISTRACIJA')}</small><strong>${roleName(state.profile.role)} <span class="status-dot"></span></strong></span></div></div><section class="section"><div class="section-heading"><div><span class="eyebrow">${t('MAKE IT YOURS','VAŠE SUDJELOVANJE')}</span><h2>${t('Everything you need. In one place.','Sve što trebate. Na jednom mjestu.')}</h2></div></div><div class="quick-grid">${[['profile','user',t('Your profile & badge','Vaš profil i akreditacija'),t('Update your details and keep your digital badge close.','Uredite podatke i preuzmite digitalnu akreditaciju.')],['papers','file',t('Share your research','Predstavite istraživanje'),t('Bring your perspective to the scientific programme.','Donesite svoju perspektivu u znanstveni program.')],['profile','download',t('Your certificate','Vaša potvrda'),t('A personalised certificate after the conference.','Personalizirana potvrda nakon konferencije.')]].map(([url,ico,title,body])=>`<a class="quick-card" href="#${url}"><span class="card-icon">${icon(ico)}</span><h3>${title}</h3><p>${body}</p><span class="card-arrow">${icon('arrow')}</span></a>`).join('')}</div></section>${notificationSection(true)}<section class="section two-column"><div><span class="eyebrow">${t('THE CONVERSATION STARTS HERE','RAZGOVOR POČINJE OVDJE')}</span><h2>${t('A meeting of<br>ideas & people.','Susret<br>ideja i ljudi.')}</h2><p class="muted">${t('PILC brings the academic community, professionals and future leaders together. Explore the first look at our three-day programme.','PILC okuplja akademsku zajednicu, profesionalce i buduće lidere. Istražite prvi pogled na trodnevni program.')}</p><a class="text-link" href="#programme">${t('View full programme','Pogledajte cijeli program')} ${icon('arrow')}</a>${btn(t('Add to calendar','Dodaj u kalendar'),'calendar','secondary','calendar')}</div><div>${schedule(true)}</div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">${t('PEOPLE & PERSPECTIVES','LJUDI I PERSPEKTIVE')}</span><h2>${t('Meet our key presenters.','Upoznajte glavne izlagače.')}</h2></div><span class="muted small">${state.presenters.length?'':t('Demo preview · Speakers to be announced','Demo pregled · Izlagači uskoro')}</span></div>${presenterCards()}</section><section class="closing-banner"><div><span class="eyebrow light">${t('LET’S CONNECT','POVEŽIMO SE')}</span><h2>${t('Your next conversation starts here.','Vaš sljedeći razgovor počinje ovdje.')}</h2></div><a class="btn gold" href="mailto:conference@par.hr">${t('Contact the team','Kontaktirajte tim')}${icon('arrow')}</a></section>`;}
function about(){return `${pageHeading(t('ABOUT PILC','O PILC-u'),t('Knowledge meets experience.','Znanje susreće iskustvo.'))}<section class="two-column section"><div class="prose"><p class="lead">${t('A meeting place for the academic community, professionals and the next generation of leaders.','Mjesto susreta akademske zajednice, profesionalaca i nove generacije lidera.')}</p><p>${t('PAR International Leadership Conference connects theoretical knowledge with professional skills. Organised by PAR University of Applied Sciences alongside international partners, PILC brings scientific research and practical leadership development into one programme.','PAR International Leadership Conference povezuje teorijska znanja i profesionalne vještine. U organizaciji Veleučilišta PAR i međunarodnih partnera, PILC spaja znanstvena istraživanja i praktičan razvoj liderskih vještina.')}</p><p>${t('The conference explores leadership and management in the economy, education, sport and tourism. Its scientific programme offers space to present research, while the professional programme encourages learning, dialogue and new connections.','Konferencija istražuje liderstvo i menadžment u gospodarstvu, obrazovanju, sportu i turizmu. Znanstveni program pruža prostor za predstavljanje istraživanja, a stručni program potiče učenje, dijalog i nova povezivanja.')}</p><div class="notice">${t('Conference languages: English and Croatian.','Službeni jezici konferencije: engleski i hrvatski.')}</div></div><div><div class="venue-photo rounded" role="img" aria-label="Hilton Rijeka Costabella"></div><p class="small muted">Hilton Rijeka Costabella Beach Resort & Spa · Rijeka / Opatija</p></div></section>${aboutDetails()}<section class="section"><span class="eyebrow">${t('PARTNERSHIP','PARTNERSTVO')}</span><h2>${t('Become part of PILC.','Postanite dio PILC-a.')}</h2><p class="muted">${t('Platinum · Gold · Silver · Friend. Sponsorship details and prices for 2027 are awaiting confirmation. Contact the organising team for information.','Platinum · Gold · Silver · Friend. Detalji i cijene sponzorstava za 2027. čekaju potvrdu. Za informacije kontaktirajte organizacijski tim.')}</p><a class="btn secondary" href="mailto:conference@par.hr?subject=PILC%202027%20Sponsorship">${t('Sponsorship enquiry','Upit za sponzorstvo')}${icon('mail')}</a></section>`;}
function profile(){const p=state.profile;const release=Date.now()>=CERTIFICATE_RELEASE;return `${pageHeading(t('YOUR PARTICIPATION','VAŠE SUDJELOVANJE'),t('My profile.','Moj profil.'),t('Your details, digital badge and certificate — all in one place.','Vaši podaci, digitalna akreditacija i potvrda na jednom mjestu.'))}<div class="profile-grid"><section class="panel"><div class="panel-heading"><h2>${t('Personal details','Osobni podaci')}</h2><span class="pill approved">${roleName(p.role)}</span></div><form id="profile-form">${profileFields(p)}<label class="field"><span>${t('Email address','E-mail adresa')}</span><input type="email" value="${e(state.user.email)}" disabled></label><p class="small muted">${t('These details appear on your badge. Your first and last name appear on your certificate.','Ovi se podaci prikazuju na akreditaciji. Ime i prezime prikazuju se na potvrdi.')}</p><p class="form-message" role="alert"></p><button class="btn primary">${t('Save changes','Spremi promjene')}${icon('check')}</button></form></section><section><div class="badge-card">${logo()}<div class="badge-body"><span class="eyebrow light">${t('DIGITAL CONFERENCE BADGE','DIGITALNA AKREDITACIJA')}</span><p class="badge-title">${e(p.title)}</p><h2>${e(p.firstName)}<br>${e(p.lastName)}</h2><p>${e(p.affiliation)}</p><span class="badge-role">${roleName(p.role)}</span><div class="badge-footer"><span>18–20 MARCH 2027<br>RIJEKA / OPATIJA</span>${icon('check')}</div><small class="badge-id">ID: ${e(p.id)}</small></div></div>${btn(t('Download badge · PDF','Preuzmi akreditaciju · PDF'),'badge','secondary wide','download')}</section></div><section class="panel certificate-panel"><div><span class="card-icon">${icon('file')}</span><span class="eyebrow">${t('A RECORD OF YOUR PARTICIPATION','POTVRDA VAŠEG SUDJELOVANJA')}</span><h2>${t('Certificate of participation','Potvrda o sudjelovanju')}</h2><p class="muted">${!release?t('Available from 21 March 2027, after the organising team confirms your attendance and publishes the template.','Dostupno od 21. ožujka 2027., nakon što organizacijski tim potvrdi prisutnost i objavi predložak.'):!p.attended?t('Your attendance has not yet been confirmed by the organising team.','Organizacijski tim još nije potvrdio vašu prisutnost.'):!state.settings?.published?t('The organising team is preparing the official certificate.','Organizacijski tim priprema službenu potvrdu.'):t('Your personalised certificate is ready.','Vaša personalizirana potvrda je spremna.')}</p><div class="button-row">${btn(t('Download certificate','Preuzmi potvrdu'),'certificate','primary',release?'download':'lock',(!release||!p.attended||!state.settings?.published)?'disabled':'')}${btn(t('Preview demo certificate','Pregledaj demo potvrdu'),'demo-certificate','secondary','eye')}</div><p class="small muted">${t('The demo uses your name and is clearly marked as a sample.','Demo koristi vaše ime i jasno je označen kao ogledni primjer.')}</p></div><div class="certificate-mini" aria-hidden="true"><span>PILC <b>2027</b></span><small>CERTIFICATE OF PARTICIPATION</small><strong>${e(p.firstName)} ${e(p.lastName)}</strong><i></i><small>18–20 MARCH 2027<br>RIJEKA / OPATIJA</small><em>DEMO</em></div></section>`;}
function papers(){const s=state.submission;return `${pageHeading(t('SCIENTIFIC PROGRAMME','ZNANSTVENI PROGRAM'),t('Share your perspective.','Podijelite svoju perspektivu.'),t('Submit your research to the PILC organising team.','Predajte svoj rad organizacijskom timu PILC-a.'))}<div class="notice">${t('Submission deadlines and formatting guidelines for 2027 will be confirmed by the organisers. For guidance, contact','Rokove predaje i upute za oblikovanje za 2027. potvrdit će organizatori. Za upute kontaktirajte')} <a href="mailto:conference@par.hr">conference@par.hr</a>.</div>${state.profile.role==='guest'?`<section class="panel empty">${icon('file')}<h2>${t('Joining as a presenter?','Želite izlagati?')}</h2><p>${t('Paper submission is available to approved presenters. Contact the organising team to update your participation role.','Predaja radova dostupna je odobrenim izlagačima. Za promjenu uloge kontaktirajte organizacijski tim.')}</p><a class="btn primary" href="mailto:conference@par.hr?subject=PILC%202027%20Presenter">${t('Contact the organisers','Kontaktirajte organizatore')}</a></section>`:`<section class="panel narrow">${s?`<div class="notice">${t('Current status','Trenutni status')}: <strong>${statusName(s.status)}</strong></div>`:''}<form id="paper-form">${field(t('Paper title','Naslov rada'),'title',s?.title,{max:250})}${field(t('Authors','Autori'),'authors',s?.authors||`${state.profile.firstName} ${state.profile.lastName}`,{max:500})}${field(t('Abstract','Sažetak'),'abstract',s?.abstract,{textarea:true,max:5000,rows:6})}${field(t('Link to your PDF paper','Poveznica na PDF rada'),'paperUrl',s?.paperUrl,{type:'url',max:2000,placeholder:'https://…'})}<p class="small muted">${t('Share a link to your PDF (for example, Google Drive or OneDrive). Grant access to conference@par.hr. The file stays with your provider; the portal saves only the link.','Podijelite poveznicu na PDF (npr. Google Drive ili OneDrive). Omogućite pristup adresi conference@par.hr. Datoteka ostaje kod vašeg pružatelja; portal sprema samo poveznicu.')}</p><p class="form-message" role="alert"></p><button class="btn primary">${s?t('Resubmit paper','Ponovno predaj rad'):t('Submit paper','Predaj rad')}${icon('arrow')}</button></form></section>`}`;}
function contact(){return `${pageHeading(t('WE’RE HERE TO HELP','OVDJE SMO ZA VAS'),t('Let’s get in touch.','Stupimo u kontakt.'))}<div class="two-column"><section class="panel contact-panel"><span class="card-icon">${icon('mail')}</span><h2>${t('PILC organising team','Organizacijski tim PILC-a')}</h2><a class="lead" href="mailto:conference@par.hr">conference@par.hr</a><a class="lead" href="tel:+38551327037">+385 51 327 037</a><hr><h3>${t('PAR University of Applied Sciences','Veleučilište PAR')}</h3><p>Trg Riječke rezolucije 4<br>51000 Rijeka, ${t('Croatia','Hrvatska')}</p></section><section class="panel"><span class="eyebrow">${t('THE VENUE','LOKACIJA')}</span><h2>Hilton Rijeka Costabella<br>Beach Resort & Spa</h2><div class="venue-photo rounded" role="img" aria-label="Hilton Rijeka Costabella"></div><p>${t('18–20 March 2027 · Rijeka / Opatija','18.–20. ožujka 2027. · Rijeka / Opatija')}</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Hilton+Rijeka+Costabella+Beach+Resort+Spa" target="_blank" rel="noopener">${t('Open map','Otvori kartu')}${icon('arrow')}</a></section></div>`;}
function privacy(){return `${pageHeading('PILC 2027',t('Privacy information','Informacije o privatnosti'))}<div class="prose narrow"><p>${t('The portal uses your name, email address, title, affiliation and participation role to manage registration, programme access, submissions, badges and certificates. Account approval and attendance are managed by the organising team.','Portal koristi ime, prezime, e-mail, titulu, ustanovu i ulogu za registraciju, pristup programu, radove, akreditacije i potvrde. Organizacijski tim upravlja odobravanjem računa i evidencijom prisutnosti.')}</p><p>${t('Authentication and participant records are handled using Firebase. Paper links point to the author’s chosen file provider. Blank certificate templates are public files hosted with this website. Your profile and submitted link are accessible in the portal to you and authorised administrators. Access to the linked file depends on its sharing settings. Language and colour theme preferences are saved in this browser. Analytics and marketing tracking are not enabled.','Prijavom i podacima sudionika upravlja Firebase. Poveznice na radove vode do pružatelja kojeg je odabrao autor. Prazni predlošci potvrda javne su datoteke uz ovu stranicu. Profil i predana poveznica u portalu dostupni su vama i ovlaštenim administratorima. Pristup povezanoj datoteci ovisi o njezinim postavkama dijeljenja. Jezik i tema spremaju se u ovom pregledniku. Analitika i marketinško praćenje nisu uključeni.')}</p><p>${t('For questions about your data or to request corrections or account removal, contact PAR University of Applied Sciences at','Za pitanja o podacima, ispravke ili zahtjev za uklanjanje računa obratite se Veleučilištu PAR na')} <a href="mailto:conference@par.hr">conference@par.hr</a>.</p><div class="notice">${t('Demo portal: the organiser must confirm the final privacy notice, retention periods and applicable terms before public registration opens.','Demo portal: organizator prije otvaranja javnih registracija treba potvrditi konačnu obavijest o privatnosti, rokove čuvanja podataka i primjenjive uvjete.')}</div><a class="btn secondary" href="${approved()?'#profile':'#'}">${t('Back','Natrag')}${icon('arrow')}</a></div>`;}
function safePhoto(url){try{return new URL(url).protocol==='https:';}catch{return false;}}
function calendarLink(s=null){return `<a class="btn small-btn" href="${e(googleCalendarUrl(s,state.lang))}" target="_blank" rel="noopener noreferrer">Google Calendar ${icon('calendar')}</a>`;}
function sessionActions(s){return `<div class="button-row session-actions">${btn(state.saved.includes(s.id)?t('Saved','Spremljeno'):t('Save session','Spremi sesiju'),'save-session','small-btn',state.saved.includes(s.id)?'check':'star',`data-id="${e(s.id)}" aria-pressed="${state.saved.includes(s.id)}"`)}${calendarLink(s)}${admin()&&!s.id.startsWith('demo-')?btn(t('Edit session','Uredi sesiju'),'edit-session','small-btn','',`data-id="${e(s.id)}"`):''}</div>`;}
function myProgramme(){return `${pageHeading(t('YOUR SELECTION','VAŠ ODABIR'),t('My programme','Moj program'),t('Saved sessions follow the latest programme in the portal. Calendar copies do not update automatically; add a changed session again.','Spremljene sesije prate aktualni program portala. Kopije u kalendaru ne ažuriraju se automatski; izmijenjenu sesiju dodajte ponovno.'))}<p class="muted">${t('All times are in Europe/Zagreb.','Sve satnice su prema vremenu Europe/Zagreb.')}</p>${['18','19','20'].map(day=>{const rows=(state.sessions.length?state.sessions:demoSessions).filter(s=>s.day===day&&state.saved.includes(s.id));return rows.length?`<section class="section"><h2>${day}. 03. 2027.</h2>${rows.map(s=>`<article class="session"><div class="session-time">${e(s.time)}<small>${e(s.end)}</small></div><div><h3>${e(langText(s))}</h3><p>${e(localizedLabel(s.room))}</p>${sessionActions(s)}</div></article>`).join('')}</section>`:'';}).join('')}${!(state.sessions.length?state.sessions:demoSessions).some(s=>state.saved.includes(s.id))?`<div class="empty"><h2>${t('Your programme starts here.','Vaš program počinje ovdje.')}</h2><p>${t('Save sessions from the programme to see them here. Removed sessions no longer appear in your selection.','Spremite sesije iz programa kako biste ih vidjeli ovdje. Obrisane sesije više se ne prikazuju u odabiru.')}</p><a class="btn primary" href="#programme">${t('Explore the programme','Istražite program')}</a></div>`:''}`;}
function noticeAudience(audience){if(audience==='all')return t('All approved participants','Svi odobreni sudionici');if(audience.startsWith('role:'))return roleName(audience.slice(5));const u=state.users.find(u=>u.id===audience.slice(5));return u?`${u.firstName} ${u.lastName}`:t('Individual recipient','Pojedinačni primatelj');}
function noticeCards(compact=false){const rows=compact?state.notices.slice(0,3):state.notices;return rows.length?rows.map(n=>`<article class="panel notice-card ${state.readNotices.includes(n.id)?'':'unread'}"><div class="panel-heading"><h3>${e(langText(n))}</h3><span class="pill">${state.readNotices.includes(n.id)?t('Read','Pročitano'):t('New','Novo')}</span></div><div class="rich-content">${cleanRichText(state.lang==='hr'?n.bodyHr:n.bodyEn)}</div>${!state.readNotices.includes(n.id)?btn(t('Mark as read','Označi pročitano'),'read-notice','text','check',`data-id="${e(n.id)}"`):''}</article>`).join(''):`<p class="muted">${t('No announcements for you yet.','Zasad nema obavijesti za vas.')}</p>`;}
function notificationSection(compact=false){return `<section class="section notifications"><div class="section-heading"><h2>${t('Announcements','Obavijesti')}</h2>${compact?`<a class="text-link" href="#notifications">${t('View all','Pogledaj sve')}${icon('arrow')}</a>`:''}</div><div id="notification-feed" data-compact="${compact}">${noticeCards(compact)}</div></section>`;}
function updateNotificationDisplay(){const feed=$('#notification-feed');if(feed)feed.innerHTML=noticeCards(feed.dataset.compact==='true');const counter=$('#notice-count');const count=state.notices.filter(n=>!state.readNotices.includes(n.id)).length;if(counter){counter.textContent=count;counter.hidden=count===0;}syncAppBadge(count);}
function richEditor(name,label){return `<div class="field"><span id="${name}-label">${label}</span><div class="editor-toolbar" role="toolbar" aria-label="${label}">${[['bold','B'],['italic','I'],['insertUnorderedList','• '+t('List','Popis')],['link',t('Link','Poveznica')]].map(([command,label])=>`<button type="button" class="small-btn btn" data-editor="${name}" data-command="${command}" aria-label="${command==='bold'?t('Bold','Podebljano'):command==='italic'?t('Italic','Kurziv'):label}">${label}</button>`).join('')}</div><div class="rich-editor" id="${name}" contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="${name}-label"></div></div>`;}
function adminNotifications(){return `<div class="admin-content-grid"><form id="notice-form" class="panel"><h2>${t('Send an announcement','Pošalji obavijest')}</h2><p class="small muted">${t('Delivered inside the portal. This does not send an email or a phone push notification.','Dostavlja se unutar portala. Ne šalje e-mail ni push obavijest na telefon.')}</p><label class="field"><span>${t('Recipients','Primatelji')}</span><select name="audience" id="notice-audience"><option value="all">${t('All approved participants','Svi odobreni sudionici')}</option>${['guest','presenter','admin'].map(r=>`<option value="role:${r}">${roleName(r)}</option>`).join('')}<option value="individual">${t('Selected people','Odabrane osobe')}</option></select></label><div id="notice-recipients" hidden><label class="field"><span>${t('Search recipients','Pretraži primatelje')}</span><input type="search" id="recipient-search"></label><div class="recipient-list">${state.users.filter(u=>u.status==='approved').map(u=>`<label class="check-label recipient-option" data-search="${e(`${u.firstName} ${u.lastName} ${u.email}`.toLowerCase())}"><input type="checkbox" name="recipient" value="${e(u.id)}"><span>${e(u.firstName)} ${e(u.lastName)}<small>${e(u.email)}</small></span></label>`).join('')}</div></div>${field(t('Subject · English','Naslov · engleski'),'titleEn','',{max:180})}${richEditor('bodyEn',t('Message · English','Poruka · engleski'))}${field(t('Subject · Croatian','Naslov · hrvatski'),'titleHr','',{max:180})}${richEditor('bodyHr',t('Message · Croatian','Poruka · hrvatski'))}<p class="small muted">${t('Paste text or links; use the toolbar for formatting. Both languages are required.','Zalijepite tekst ili poveznice; za oblikovanje koristite alatnu traku. Oba jezika su obavezna.')}</p><p class="form-message" role="alert"></p><button type="submit" class="btn primary">${t('Send announcement','Pošalji obavijest')}${icon('mail')}</button></form><section class="panel"><h2>${t('Sent announcements','Poslane obavijesti')}</h2>${state.sentNotices.length?state.sentNotices.map(n=>`<article class="admin-item"><span class="pill">${e(noticeAudience(n.audience))}</span><h3>${e(langText(n))}</h3><div class="rich-content">${cleanRichText(state.lang==='hr'?n.bodyHr:n.bodyEn)}</div>${btn(t('Remove announcement','Ukloni obavijest'),'delete-notice','small-btn danger','',`data-id="${e(n.id)}"`)}</article>`).join(''):`<p class="muted">${t('No announcements sent yet.','Još nema poslanih obavijesti.')}</p>`}</section></div>`;}
function aboutDetails(){return `<section class="section two-column about-story"><figure><img class="editorial-photo" src="assets/pilc-2023.jpg" alt="${t('Participants at PILC 2023','Sudionici na PILC-u 2023.')}" loading="lazy"><figcaption>${t('From the PILC archive · 2023 edition','Iz PILC arhive · izdanje 2023.')}</figcaption></figure><div><span class="eyebrow">${t('WHO IS PILC FOR?','KOME JE PILC NAMIJENJEN?')}</span><h2>${t('Different backgrounds.<br>A shared ambition.','Različita iskustva.<br>Zajednička ambicija.')}</h2><p class="muted">${t('For business leaders and managers, people driving digital transformation, academics, researchers, consultants and students. PILC brings experience and fresh perspectives to the same table.','Za poslovne lidere i menadžere, stručnjake digitalne transformacije, akademsku zajednicu, istraživače, konzultante i studente. PILC okuplja iskustvo i nove perspektive za istim stolom.')}</p><ul class="check-list"><li>${icon('check')}${t('Business & professional community','Poslovna i stručna zajednica')}</li><li>${icon('check')}${t('Academia & research','Akademska zajednica i istraživanje')}</li><li>${icon('check')}${t('Students & future leaders','Studenti i budući lideri')}</li></ul></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">${t('WHY ATTEND?','ZAŠTO SUDJELOVATI?')}</span><h2>${t('Take a new perspective with you.','Ponesite novu perspektivu.')}</h2></div></div><div class="quick-grid">${[['star',t('Develop your leadership','Razvijajte svoje liderstvo'),t('Reflect on your leadership style, understand how leaders and managers work together, and explore stronger organisational cultures.','Preispitajte svoj liderski stil, razumijte odnos lidera i menadžera te istražite kako razvijati snažnije organizacijske kulture.')],['user',t('Make meaningful connections','Povežite se s drugima'),t('Exchange ideas with people from different sectors and build relationships that can grow into future collaborations.','Razmijenite ideje s ljudima iz različitih područja i izgradite odnose koji mogu prerasti u buduću suradnju.')],['file',t('Connect research with practice','Povežite istraživanje i praksu'),t('Bring scientific insights into real conversations through research presentations, panels and professional learning.','Prenesite znanstvene spoznaje u stvarne razgovore kroz predstavljanje istraživanja, panele i stručno učenje.')]].map(([ico,title,body])=>`<article class="quick-card"><span class="card-icon">${icon(ico)}</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></section><section class="section mission-grid"><article><span class="eyebrow">${t('OUR MISSION','NAŠA MISIJA')}</span><h2>${t('Knowledge that empowers.','Znanje koje osnažuje.')}</h2><p class="muted">${t('Support learning and leadership development that benefits people, organisations and society — while helping young people build knowledge and confidence.','Podržati učenje i razvoj liderstva za dobrobit pojedinaca, organizacija i društva te pomoći mladima u stjecanju znanja i samopouzdanja.')}</p></article><article><span class="eyebrow">${t('OUR VISION','NAŠA VIZIJA')}</span><h2>${t('Science and business, together.','Znanost i poslovanje, zajedno.')}</h2><p class="muted">${t('An international meeting place where research, innovation and experience meet. A space to strengthen management skills, professional networks and an entrepreneurial mindset.','Međunarodno mjesto susreta istraživanja, inovacija i iskustva. Prostor za razvoj upravljačkih vještina, profesionalnih mreža i poduzetničkog načina razmišljanja.')}</p></article></section>`;}
function adminView(){return `${pageHeading(t('ORGANISER WORKSPACE','PROSTOR ORGANIZATORA'),t('Conference management.','Upravljanje konferencijom.'),t('Manage registrations, programme, presenters and certificates.','Upravljajte registracijama, programom, izlagačima i potvrdama.'))}<div class="admin-stats">${[[state.users.filter(u=>u.status==='pending').length,t('Pending approval','Čeka odobrenje')],[state.users.filter(u=>u.status==='approved').length,t('Approved participants','Odobreni sudionici')],[state.users.filter(u=>u.attended).length,t('Attendance confirmed','Potvrđena prisutnost')],[state.submissions.length,t('Submitted papers','Predani radovi')]].map(([n,l])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="tab-bar">${[['people',t('Participants','Sudionici')],['notifications',t('Announcements','Obavijesti')],['programme',t('Programme','Program')],['my-programme',t('My programme','Moj program')],['presenters',t('Presenters','Izlagači')],['papers',t('Papers','Radovi')],['certificates',t('Certificates','Potvrde')]].map(([v,l])=>`<button data-admin-tab="${v}" class="${state.adminTab===v?'selected':''}">${l}</button>`).join('')}</div>${state.adminTab==='notifications'?adminNotifications():state.adminTab==='people'?adminPeople():state.adminTab==='programme'?adminProgramme():state.adminTab==='presenters'?adminPresenters():state.adminTab==='papers'?adminPapers():adminCertificates()}`;}
function adminPeople(){return `<section class="panel"><div class="toolbar"><label class="field"><span>${t('Search participants','Pretraži sudionike')}</span><input id="people-search" type="search" value="${e(state.search)}" placeholder="${t('Name, email or organisation','Ime, e-mail ili ustanova')}"></label><label class="field"><span>${t('Status','Status')}</span><select id="people-filter">${['all','pending','approved','rejected'].map(v=>`<option value="${v}" ${v===state.filter?'selected':''}>${v==='all'?t('All participants','Svi sudionici'):statusName(v)}</option>`).join('')}</select></label>${btn(t('Export CSV','Izvezi CSV'),'export-csv','secondary','download')}${btn(t('Refresh','Osvježi'),'reload-admin','secondary','')}</div><div id="people-list">${peopleList()}</div></section>`;}
function peopleList(){const users=state.users.filter(u=>(state.filter==='all'||u.status===state.filter)&&`${u.firstName} ${u.lastName} ${u.email} ${u.affiliation}`.toLowerCase().includes(state.search.toLowerCase()));return users.length?`<div class="table-scroll"><table><thead><tr><th>${t('Participant','Sudionik')}</th><th>${t('Status & role','Status i uloga')}</th><th>${t('Attendance','Prisutnost')}</th><th>${t('Actions','Radnje')}</th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${e(u.firstName)} ${e(u.lastName)}</strong><span>${e(u.email)}</span><small>${e(u.affiliation)}</small><small class="muted">${t('Requested','Željena uloga')}: ${roleName(u.requestedRole)}</small></td><td><span class="pill ${e(u.status)}">${statusName(u.status)}</span><select aria-label="${t('Role for','Uloga za')} ${e(u.firstName)}" data-user-role="${e(u.id)}" ${u.id===state.user.uid?'disabled':''}>${['guest','presenter','admin'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${roleName(r)}</option>`).join('')}</select></td><td><label class="check-label"><input type="checkbox" data-attendance="${e(u.id)}" ${u.attended?'checked':''} ${u.status!=='approved'?'disabled':''}>${t('Present','Prisutan/na')}</label></td><td><div class="table-actions">${u.id!==state.user.uid?`${u.status!=='approved'?btn(t('Approve','Odobri'),'approve','small-btn','',`data-id="${e(u.id)}"`):''}${u.status!=='rejected'?btn(t('Reject / revoke','Odbij / ukini'),'reject','small-btn danger','',`data-id="${e(u.id)}"`):''}`:`<span class="small muted">${t('Your account','Vaš račun')}</span>`}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('No participants match your search.','Nema sudionika koji odgovaraju pretrazi.')}</div>`;}
function sessionForm(s={}){return `<form id="session-form" class="panel"><h2>${s.id?t('Edit session','Uredi sesiju'):t('Add a session','Dodaj sesiju')}</h2><div class="form-grid">${field(t('Title · English','Naslov · engleski'),'titleEn',s.titleEn,{max:250})}${field(t('Title · Croatian','Naslov · hrvatski'),'titleHr',s.titleHr,{max:250})}<label class="field"><span>${t('Day','Dan')}</span><select name="day">${['18','19','20'].map(d=>`<option value="${d}" ${s.day===d?'selected':''}>${d}. 03. 2027.</option>`).join('')}</select></label>${field(t('Format (EN / HR)','Vrsta (EN / HR)'),'type',s.type,{placeholder:'Panel / Panel',max:80})}${field(t('Start','Početak'),'time',s.time,{type:'time'})}${field(t('End','Završetak'),'end',s.end,{type:'time'})}${field(t('Room (EN / HR)','Dvorana (EN / HR)'),'room',s.room,{max:120})}</div><p class="form-message" role="alert"></p><div class="button-row"><button class="btn primary">${t('Save session','Spremi sesiju')}${icon('check')}</button>${s.id?btn(t('Cancel editing','Odustani od uređivanja'),'cancel-session','secondary',''):''}</div></form>`;}
function adminProgramme(){return `<p class="notice">${t('Published entries replace the demo programme. Use both languages for titles, room names and format labels.','Objavljene stavke zamjenjuju demo program. Unesite oba jezika za naslove, nazive dvorana i vrste sesija.')}</p>${!state.sessions.length?btn(t('Load demo into editor','Učitaj demo za uređivanje'),'seed-programme','secondary','calendar'):''}<div class="admin-content-grid">${sessionForm(state.editSession||{})}<section class="panel"><h2>${t('Published programme','Objavljeni program')}</h2>${state.sessions.length?state.sessions.map(s=>`<div class="admin-item"><span class="eyebrow">${e(s.day)}.03. · ${e(s.time)}–${e(s.end)}</span><h3>${e(langText(s))}</h3><div class="button-row">${btn(t('Edit','Uredi'),'edit-session','small-btn','',`data-id="${e(s.id)}"`)}${btn(t('Delete','Obriši'),'delete-session','small-btn danger','',`data-id="${e(s.id)}"`)}</div></div>`).join(''):`<p class="muted">${t('The site currently displays a labelled demo programme.','Stranica trenutačno prikazuje označeni demo program.')}</p>`}</section></div>`;}
function adminPresenters(){const p=state.editPresenter||{};return `<div class="admin-content-grid"><form id="presenter-form" class="panel"><h2>${p.id?t('Edit presenter','Uredi izlagača'):t('Add a presenter','Dodaj izlagača')}</h2>${field(t('Full name','Ime i prezime'),'name',p.name,{max:160})}${field(t('Role / topic · English','Uloga / tema · engleski'),'titleEn',p.titleEn)}${field(t('Role / topic · Croatian','Uloga / tema · hrvatski'),'titleHr',p.titleHr)}${field(t('Biography · English','Biografija · engleski'),'bioEn',p.bioEn,{textarea:true,max:2000})}${field(t('Biography · Croatian','Biografija · hrvatski'),'bioHr',p.bioHr,{textarea:true,max:2000})}${field(t('Photo URL · HTTPS','Poveznica fotografije · HTTPS'),'photo',p.photo,{type:'url',optional:true,max:1500})}<p class="small muted">${t('Use a photo you have permission to publish. Without a photo, a neutral profile illustration is shown.','Koristite fotografiju za koju imate dopuštenje objave. Bez fotografije prikazuje se neutralna ilustracija profila.')}</p><p class="form-message" role="alert"></p><div class="button-row"><button class="btn primary">${t('Save presenter','Spremi izlagača')}</button>${p.id?btn(t('Cancel','Odustani'),'cancel-presenter','secondary',''):''}</div></form><section class="panel"><h2>${t('Published presenters','Objavljeni izlagači')}</h2>${state.presenters.length?state.presenters.map(p=>`<div class="admin-item"><h3>${e(p.name)}</h3><p>${e(langText(p))}</p><div class="button-row">${btn(t('Edit','Uredi'),'edit-presenter','small-btn','',`data-id="${e(p.id)}"`)}${btn(t('Delete','Obriši'),'delete-presenter','small-btn danger','',`data-id="${e(p.id)}"`)}</div></div>`).join(''):`<p class="muted">${t('No confirmed presenters yet. The home page displays clearly labelled placeholders.','Još nema potvrđenih izlagača. Početna prikazuje jasno označene ogledne kartice.')}</p>`}</section></div>`;}
function adminPapers(){return `<section class="panel"><h2>${t('Paper review','Pregled radova')}</h2>${state.submissions.length?state.submissions.map(s=>`<article class="admin-item"><span class="pill">${statusName(s.status)}</span><h3>${e(s.title)}</h3><p>${e(s.authors)}</p><details><summary>${t('Read abstract','Pročitaj sažetak')}</summary><p class="pre-wrap">${e(s.abstract)}</p></details><div class="button-row">${s.paperUrl&&safePhoto(s.paperUrl)?`<a class="btn secondary" href="${e(s.paperUrl)}" target="_blank" rel="noopener noreferrer">${t('Open paper','Otvori rad')}${icon('file')}</a>`:`<span class="small muted">${t('Ask the author for a paper link.','Zatražite od autora poveznicu na rad.')}</span>`}<label class="field"><span>${t('Review status','Status pregleda')}</span><select data-review="${e(s.id)}">${['submitted','accepted','revision','rejected'].map(v=>`<option value="${v}" ${s.status===v?'selected':''}>${statusName(v)}</option>`).join('')}</select></label></div></article>`).join(''):`<p class="muted">${t('No papers submitted yet.','Još nema predanih radova.')}</p>`}</section>`;}
function adminCertificates(){const s=state.settings||{};return `<div class="admin-content-grid"><form id="certificate-form" class="panel"><h2>${t('Automatic certificates','Automatske potvrde')}</h2><p class="muted">${t('Add a PDF template with a blank name line to the site’s assets/documents folder, then enter its path below. Each participant’s first and last name is inserted automatically on the first page. Coordinates are percentages from the left and top.','Dodajte PDF predložak s praznom crtom za ime u mapu assets/documents stranice, a zatim ispod unesite putanju. Ime i prezime svakog sudionika automatski se upisuju na prvu stranicu. Koordinate su postotci od lijevog i gornjeg ruba.')}</p>${field(t('Template path on this site','Putanja predloška na stranici'),'templatePath',s.templatePath||DEFAULT_TEMPLATE,{max:200,placeholder:'assets/documents/certificate-template.pdf'})}<p class="small muted">${t('Templates are public files. Do not put personal certificates or private papers in the repository.','Predlošci su javne datoteke. Osobne potvrde i privatne radove nemojte stavljati u repozitorij.')}</p><div class="form-grid">${field(t('Name centre · X (%)','Središte imena · X (%)'),'x',s.x??50,{type:'number',extra:'min="10" max="90" step="0.1"'})}${field(t('Name baseline · Y (%)','Osnovna crta imena · Y (%)'),'y',s.y??51,{type:'number',extra:'min="10" max="90" step="0.1"'})}${field(t('Font size (pt)','Veličina slova (pt)'),'fontSize',s.fontSize??30,{type:'number',extra:'min="10" max="60"'})}</div><label class="check-label"><input type="checkbox" name="published" ${s.published?'checked':''}>${t('Publish certificates after the conference','Objavi potvrde nakon konferencije')}</label><p class="small muted">${t('Downloads require approved registration and confirmed attendance, and the download button opens on 21 March 2027 (Zagreb time). The blank PDF template itself is publicly accessible.','Preuzimanje zahtijeva odobren račun i evidentiranu prisutnost a gumb za preuzimanje otvara se 21. ožujka 2027. (vrijeme u Zagrebu). Sam prazan PDF predložak javno je dostupan.')}</p><p class="form-message" role="alert"></p><div class="button-row"><button class="btn primary">${t('Save settings','Spremi postavke')}</button>${btn(t('Preview with my name','Pregled s mojim imenom'),'preview-template','secondary','eye')}</div></form><section class="panel"><span class="eyebrow">${t('READY TO TRY','ISPROBAJTE')}</span><h2>${t('A PILC-branded starting point.','Početni predložak u PILC bojama.')}</h2><p class="muted">${t('Download the sample template with a blank name line, or preview it with your profile name. The demo is visibly marked and has no official signature.','Preuzmite ogledni predložak s praznom crtom za ime ili pregledajte primjer s imenom iz profila. Demo je vidljivo označen i nema službeni potpis.')}</p><div class="button-row">${btn(t('Download blank demo','Preuzmi prazan demo'),'blank-certificate','secondary','download')}${btn(t('Personalised demo','Personalizirani demo'),'demo-certificate','secondary','eye')}</div><div class="notice">${t('Confirm the wording and final design before issuing official certificates. The portal personalises PDFs; it does not add a digital signature.','Potvrdite tekst i konačni dizajn prije izdavanja službenih potvrda. Portal personalizira PDF-ove; ne dodaje digitalni potpis.')}</div></section></div>`;}
function route(){return location.hash.slice(1).split('?')[0]||'home';}
let unsubscribeProfile,unsubscribeNotices,loadVersion=0;
function render(){api.setLanguage?.(state.lang);document.documentElement.lang=state.lang;document.documentElement.dataset.theme=state.theme;document.title=`PILC 2027 · ${t('Participant portal','Portal za sudionike')}`;if(!state.authReady||(state.user&&!state.profileReady)){root.innerHTML=`${header()}<main id="main" class="boot" aria-busy="true">PILC 2027<span>${t('Loading your space…','Učitavanje vašeg prostora…')}</span></main>`;return;}if(route()==='privacy'){root.innerHTML=`${header(approved())}<main id="main" class="container page">${privacy()}</main>${footer()}`;return;}if(!state.user){root.innerHTML=authView();return;}if(state.error&&!state.profile){root.innerHTML=`${header()}<main id="main" class="container gate"><h1>${t('We couldn’t load your account.','Nismo uspjeli učitati račun.')}</h1><p>${e(state.error)}</p>${btn(t('Try again','Pokušaj ponovno'),'reload','primary')}${btn(t('Sign out','Odjava'),'logout','secondary','')}</main>`;return;}if(!approved()){root.innerHTML=gateView();return;}const r=route();const views={home,about,'my-programme':myProgramme,notifications:()=>`${pageHeading('PILC 2027',t('Your announcements','Vaše obavijesti'))}${btn(t('Enable app icon badge','Omogući broj na ikoni aplikacije'),'enable-badge','secondary','bell')}<p class="small muted">${t('Availability depends on your device. Updates arrive while the app is active; background push is not enabled.','Dostupnost ovisi o uređaju. Broj se ažurira dok je aplikacija aktivna; pozadinske push obavijesti nisu uključene.')}</p>${notificationSection()}`,programme:()=>`${pageHeading(t('THREE DAYS. NEW PERSPECTIVES.','TRI DANA. NOVE PERSPEKTIVE.'),t('The programme.','Program.'),t('18–20 March 2027 · Hilton Rijeka Costabella Beach Resort & Spa','18.–20. ožujka 2027. · Hilton Rijeka Costabella Beach Resort & Spa'))}<div class="button-row">${calendarLink()}${btn(t('Download calendar file','Preuzmi kalendarsku datoteku'),'calendar','secondary','calendar')}${admin()?`<a class="btn secondary" href="#admin" data-manage-programme>${t('Manage programme','Upravljaj programom')}</a>`:''}</div>${schedule()}`,profile,papers,contact,admin:()=>admin()?adminView():`<div class="empty"><h1>${t('Administrator access required','Potreban je administratorski pristup')}</h1><a href="#home">${t('Back to home','Natrag na početnu')}</a></div>`};root.innerHTML=`${header(true)}<main id="main" class="container page">${state.error?`<div class="notice error">${e(state.error)} ${btn(t('Retry','Pokušaj ponovno'),'reload-data','small-btn','')}</div>`:''}${state.loading?`<div class="loading-line" role="status">${t('Updating…','Osvježavanje…')}</div>`:''}${(views[r]||views.home)()}</main>${footer()}`;}
async function loadData(){const version=++loadVersion;if(!approved())return;state.loading=true;state.error='';render();try{const values=await Promise.all([api.sessions(),api.presenters(),api.certificateSettings(),state.profile.role!=='guest'?api.submission():Promise.resolve(null),admin()?api.users():Promise.resolve([]),admin()?api.submissions():Promise.resolve([]),api.savedSessions(),api.readNotifications(),admin()?api.sentNotifications():Promise.resolve([])]);if(version!==loadVersion||!approved())return;[state.sessions,state.presenters,state.settings,state.submission,state.users,state.submissions,state.saved,state.readNotices,state.sentNotices]=values;syncAppBadge(state.notices.filter(n=>!state.readNotices.includes(n.id)).length);}catch(err){if(version===loadVersion)state.error=errorText(err);}finally{if(version===loadVersion){state.loading=false;render();}}}
api.observeAuth(user=>{unsubscribeProfile?.();unsubscribeNotices?.();syncAppBadge(0);state.saved=[];state.notices=[];state.readNotices=[];state.sentNotices=[];loadVersion++;state.user=user;state.authReady=true;state.profileReady=!user;state.profile=null;state.error='';state.users=[];state.submissions=[];state.sessions=[];state.presenters=[];state.settings=null;state.submission=null;render();if(user){unsubscribeProfile=api.observeProfile(user.uid,p=>{const wasApproved=approved(),oldRole=state.profile?.role;state.profile=p;state.profileReady=true;render();if(approved()&&(!wasApproved||oldRole!==p.role)){unsubscribeNotices?.();state.notices=[];unsubscribeNotices=api.observeNotifications(p.role,notices=>{if(approved()){state.notices=notices;updateNotificationDisplay();}},err=>toast(errorText(err)));loadData();}if(!approved()){syncAppBadge(0);unsubscribeNotices?.();state.notices=[];state.saved=[];state.readNotices=[];state.sentNotices=[];loadVersion++;state.users=[];state.submissions=[];state.sessions=[];state.presenters=[];state.settings=null;state.submission=null;}},err=>{state.error=errorText(err);state.profileReady=true;render();});}});
function errorText(err){const code=err?.code||'';if(code.includes('invalid-credential')||code.includes('wrong-password')||code.includes('user-not-found'))return t('The email or password is incorrect. Please try again.','E-mail ili lozinka nisu ispravni. Pokušajte ponovno.');if(code.includes('email-already-in-use'))return t('An account with this email already exists. Sign in or reset your password.','Račun s ovom adresom već postoji. Prijavite se ili resetirajte lozinku.');if(code.includes('too-many-requests'))return t('Too many attempts. Please try again later.','Previše pokušaja. Pokušajte kasnije.');if(code.includes('weak-password'))return t('Choose a stronger password with at least 8 characters.','Odaberite jaču lozinku s najmanje 8 znakova.');if(code.includes('permission-denied')||code.includes('unauthorized'))return t('Access denied. Check your account approval or contact the organising team.','Pristup nije dopušten. Provjerite odobrenje računa ili kontaktirajte organizatore.');if(code.includes('network')||code.includes('unavailable'))return t('Connection unavailable. Check your internet connection and try again.','Veza nije dostupna. Provjerite internet i pokušajte ponovno.');if(code.includes('object-not-found'))return t('The file is not available yet. Please contact the organising team.','Datoteka još nije dostupna. Kontaktirajte organizatore.');if(code.includes('operation-not-allowed')||code.includes('configuration'))return t('Sign-in is not configured yet. Please contact the organising team.','Prijava još nije postavljena. Kontaktirajte organizatore.');return err?.userMessage||t('We couldn’t complete this action. Please try again or contact conference@par.hr.','Nismo mogli dovršiti radnju. Pokušajte ponovno ili pišite na conference@par.hr.');}
function fail(en,hr){throw {userMessage:t(en,hr)};}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6500);}
async function action(button,fn){button.disabled=true;button.setAttribute('aria-busy','true');try{await fn();}catch(err){toast(errorText(err));}finally{button.disabled=false;button.removeAttribute('aria-busy');}}
function formData(form){return Object.fromEntries([...new FormData(form)].filter(([,v])=>typeof v==='string').map(([k,v])=>[k,v.trim()]));}
function personal(data){return {firstName:data.firstName,lastName:data.lastName,title:data.title,affiliation:data.affiliation};}
document.addEventListener('submit',async ev=>{const form=ev.target;if(!form.id)return;ev.preventDefault();const button=form.querySelector('button[type="submit"],button.btn:not([type="button"])');if(button?.disabled)return;const data=formData(form),message=form.querySelector('.form-message');button.disabled=true;button.setAttribute('aria-busy','true');if(message)message.textContent='';try{
  if(form.id==='auth-form'){
    if(state.authMode==='login')await api.login(data.email,form.elements.password.value,!!data.remember);
    else if(state.authMode==='reset'){await api.reset(data.email);toast(t('If an account exists, a reset link will arrive shortly.','Ako račun postoji, poveznica za resetiranje uskoro će stići.'));state.authMode='login';render();}
    else {await api.register({...personal(data),email:data.email,requestedRole:data.requestedRole},form.elements.password.value);toast(t('Account created. Your registration is awaiting approval.','Račun je izrađen. Vaša registracija čeka odobrenje.'));}
  }else if(form.id==='complete-form'){await api.completeProfile({...personal(data),requestedRole:data.requestedRole});toast(t('Registration sent for approval.','Registracija je poslana na odobrenje.'));}
  else if(form.id==='profile-form'){await api.saveProfile(personal(data));toast(t('Your profile has been saved.','Profil je spremljen.'));}
  else if(form.id==='notice-form'){
    const bodyEn=cleanRichText($('#bodyEn').innerHTML),bodyHr=cleanRichText($('#bodyHr').innerHTML);
    if(!$('#bodyEn').textContent.trim()||!$('#bodyHr').textContent.trim()||bodyEn.length>20000||bodyHr.length>20000)fail('Add a message in both languages (up to 20,000 characters each).','Unesite poruku na oba jezika (do 20.000 znakova po jeziku).');
    const selected=[...new FormData(form).getAll('recipient')];
    if(data.audience==='individual'&&(!selected.length||selected.length>100))fail('Select between 1 and 100 recipients.','Odaberite od 1 do 100 primatelja.');
    const audiences=data.audience==='individual'?selected.map(id=>'user:'+id):[data.audience];
    await api.sendNotification({titleEn:data.titleEn,titleHr:data.titleHr,bodyEn,bodyHr},audiences);
    await loadData();toast(t('Announcement sent.','Obavijest je poslana.'));
  }
  else if(form.id==='paper-form'){if(!safePhoto(data.paperUrl))fail('Use an HTTPS link to your paper.','Koristite HTTPS poveznicu na rad.');await api.submit({title:data.title,authors:data.authors,abstract:data.abstract,paperUrl:data.paperUrl});await loadData();toast(t('Your paper link has been submitted.','Poveznica na rad je predana.'));}
  else if(form.id==='session-form'){if(data.end<=data.time)fail('End time must be after the start time.','Završetak mora biti nakon početka.');if(state.editSession)await api.editSession(state.editSession.id,data);else await api.addSession(data);state.editSession=null;await loadData();toast(t('Session saved.','Sesija je spremljena.'));}
  else if(form.id==='presenter-form'){if(data.photo&&!safePhoto(data.photo))fail('Use an HTTPS photo URL.','Koristite HTTPS poveznicu fotografije.');if(state.editPresenter)await api.editPresenter(state.editPresenter.id,data);else await api.addPresenter(data);state.editPresenter=null;await loadData();toast(t('Presenter saved.','Izlagač je spremljen.'));}
  else if(form.id==='certificate-form'){if(!validTemplatePath(data.templatePath))fail('Use a path such as assets/documents/certificate-template.pdf.','Koristite putanju poput assets/documents/certificate-template.pdf.');const template=await loadTemplate(data.templatePath);await certificate(state.profile,{demo:true,template,settings:data});await api.saveCertificate({templatePath:data.templatePath,x:Number(data.x),y:Number(data.y),fontSize:Number(data.fontSize),published:!!data.published,hasTemplate:true});await loadData();toast(t('Certificate settings saved.','Postavke potvrde spremljene.'));}
}catch(err){if(message?.isConnected)message.textContent=errorText(err);else toast(errorText(err));}finally{button.disabled=false;button.removeAttribute('aria-busy');}});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.day){state.day=b.dataset.day;render();return;}if(b.dataset.adminTab){state.adminTab=b.dataset.adminTab;render();return;}const a=b.dataset.action;if(!a)return;
  if(['language','theme'].includes(a)){if(a==='language')state.lang=state.lang==='en'?'hr':'en';else state.theme=state.theme==='light'?'dark':'light';try{localStorage.setItem('pilc-language',state.lang);localStorage.setItem('pilc-theme',state.theme);}catch{}render();return;}
  if(a.endsWith('-mode')){state.authMode=a.replace('-mode','');render();return;}
  if(a==='password'){const input=$('[name="password"]');input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?t('Show password','Prikaži lozinku'):t('Hide password','Sakrij lozinku'));return;}
  if(a==='menu'){$('#navigation').classList.toggle('open');b.setAttribute('aria-expanded',$('#navigation').classList.contains('open'));return;}
  action(b,async()=>{
    if(a==='logout'){await api.logout();location.hash='';}
    else if(a==='refresh'){state.user=await api.refresh();render();if(approved())await loadData();else toast(t('Status refreshed.','Status je osvježen.'));}
    else if(a==='reload')location.reload();
    else if(a==='reload-data'||a==='reload-admin')await loadData();
    else if(a==='install-app'){toast(await installApp(state.lang==='hr'));}
    else if(a==='enable-badge'){toast(await enableBadge(state.lang==='hr'));syncAppBadge(state.notices.filter(n=>!state.readNotices.includes(n.id)).length);}
    else if(a==='save-session'){const id=b.dataset.id,next=!state.saved.includes(id);await api.saveSession(id,next);state.saved=next?[...state.saved,id]:state.saved.filter(v=>v!==id);render();}
    else if(a==='read-notice'){await api.markRead(b.dataset.id);state.readNotices.push(b.dataset.id);updateNotificationDisplay();}
    else if(a==='delete-notice'){if(confirm(t('Remove this announcement from the portal?','Ukloniti ovu obavijest iz portala?'))){await api.removeNotification(b.dataset.id);await loadData();}}
    else if(a==='export-csv'){const rows=state.users.filter(u=>(state.filter==='all'||u.status===state.filter)&&`${u.firstName} ${u.lastName} ${u.email} ${u.affiliation}`.toLowerCase().includes(state.search.toLowerCase()));download(participantsCsv(rows),'PILC-2027-participants.csv','text/csv;charset=utf-8');}
    else if(a==='badge')download(await badge(state.profile,roleName(state.profile.role)),'PILC-2027-badge.pdf');
    else if(a==='demo-certificate')download(await certificate(state.profile,{demo:true}),'PILC-2027-DEMO-certificate.pdf');
    else if(a==='blank-certificate')download(await certificate({firstName:'',lastName:''},{demo:true}),'PILC-2027-DEMO-template.pdf');
    else if(a==='certificate'){if(!approved()||!state.profile.attended||!state.settings?.published||Date.now()<CERTIFICATE_RELEASE)fail('Your certificate is not available yet.','Vaša potvrda još nije dostupna.');const template=await loadTemplate(state.settings.templatePath||DEFAULT_TEMPLATE);download(await certificate(state.profile,{template,settings:state.settings}),'PILC-2027-certificate.pdf');}
    else if(a==='preview-template'){const settings=formData($('#certificate-form'));const template=await loadTemplate(settings.templatePath);download(await certificate(state.profile,{demo:true,template,settings}),'PILC-2027-template-preview.pdf');}
    else if(a==='calendar'){download('BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//PILC//2027//EN\r\nBEGIN:VEVENT\r\nUID:pilc-2027@par.hr\r\nDTSTAMP:20261029T000000Z\r\nDTSTART;VALUE=DATE:20270318\r\nDTEND;VALUE=DATE:20270321\r\nSUMMARY:PILC 2027 - Where leaders meet future leaders\r\nLOCATION:Hilton Rijeka Costabella Beach Resort & Spa\\, Rijeka / Opatija\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n','PILC-2027.ics','text/calendar');}
    else if(a==='approve'||a==='reject'){if(a==='reject'&&!confirm(t('Reject or revoke this participant’s access?','Odbiti ili ukinuti pristup ovom sudioniku?')))return;const u=state.users.find(u=>u.id===b.dataset.id);await api.updateUser(u.id,a==='approve'?{status:'approved',role:u.role==='guest'&&u.requestedRole==='presenter'?'presenter':u.role}:{status:'rejected',attended:false});await loadData();}
    else if(a==='seed-programme'){if(!confirm(t('Publish the example programme for editing? These sessions are illustrative.','Objaviti ogledni program za uređivanje? Sesije su primjeri.')))return;for(const {id,...s} of demoSessions)await api.addSession({...s,titleEn:'[DEMO] '+s.titleEn,titleHr:'[DEMO] '+s.titleHr});await loadData();}
    else if(a==='edit-session'){state.editSession=state.sessions.find(s=>s.id===b.dataset.id);state.adminTab='programme';location.hash='admin';render();$('#session-form input')?.focus();}
    else if(a==='cancel-session'){state.editSession=null;render();}
    else if(a==='delete-session'){if(confirm(t('Delete this session?','Obrisati ovu sesiju?'))){await api.removeSession(b.dataset.id);await loadData();}}
    else if(a==='edit-presenter'){state.editPresenter=state.presenters.find(p=>p.id===b.dataset.id);render();$('#presenter-form input').focus();}
    else if(a==='cancel-presenter'){state.editPresenter=null;render();}
    else if(a==='delete-presenter'){if(confirm(t('Delete this presenter?','Obrisati ovog izlagača?'))){await api.removePresenter(b.dataset.id);await loadData();}}
  });
});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='people-filter'){state.filter=el.value;$('#people-list').innerHTML=peopleList();return;}if(!el.dataset.userRole&&!el.dataset.attendance&&!el.dataset.review)return;el.disabled=true;try{if(el.dataset.userRole){if(el.value==='admin'&&!confirm(t('Grant administrator access? This allows management of all participants and content.','Dodijeliti administratorski pristup? To omogućuje upravljanje svim sudionicima i sadržajem.'))){render();return;}await api.updateUser(el.dataset.userRole,{role:el.value});}else if(el.dataset.attendance)await api.updateUser(el.dataset.attendance,{attended:el.checked});else await api.review(el.dataset.review,el.value);await loadData();toast(t('Updated.','Ažurirano.'));}catch(err){toast(errorText(err));render();}});
document.addEventListener('input',ev=>{if(ev.target.id==='people-search'){state.search=ev.target.value;$('#people-list').innerHTML=peopleList();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);document.querySelector('.page-heading h1')?.focus({preventScroll:true});});
window.addEventListener('offline',()=>toast(t('You are offline. Changes cannot be saved until you reconnect.','Niste povezani. Promjene nije moguće spremiti dok se ponovno ne povežete.')));
document.addEventListener('click',ev=>{if(ev.target.closest('[data-manage-programme]')){state.adminTab='programme';if(route()==='admin')render();}});
document.addEventListener('change',ev=>{if(ev.target.id==='notice-audience')$('#notice-recipients').hidden=ev.target.value!=='individual';});
document.addEventListener('input',ev=>{if(ev.target.id==='recipient-search'){const q=ev.target.value.toLowerCase();document.querySelectorAll('.recipient-option').forEach(label=>{label.hidden=!label.dataset.search.includes(q);});}});
// Preserve selection when a formatting button receives a mouse click.
document.addEventListener('mousedown',ev=>{if(ev.target.closest('[data-command]'))ev.preventDefault();});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-command]');if(!b)return;const editor=document.getElementById(b.dataset.editor);const selection=window.getSelection();if(!selection?.anchorNode||!editor.contains(selection.anchorNode)){editor.focus();const range=document.createRange();range.selectNodeContents(editor);range.collapse(false);selection.removeAllRanges();selection.addRange(range);}if(b.dataset.command==='link'){const url=prompt(t('Paste a web or email link (https://… or mailto:…).','Zalijepite web ili e-mail poveznicu (https://… ili mailto:…).'));if(url===null)return;const safe=safeLink(url.trim());if(!safe){toast(t('Use a valid http, https or mailto link.','Koristite valjanu http, https ili mailto poveznicu.'));return;}if(selection.isCollapsed)document.execCommand('insertHTML',false,`<a href="${e(safe)}">${e(safe)}</a>`);else document.execCommand('createLink',false,safe);}else document.execCommand(b.dataset.command,false);});
document.addEventListener('paste',ev=>{if(!ev.target.closest('.rich-editor'))return;ev.preventDefault();const plain=ev.clipboardData.getData('text/plain');const html=ev.clipboardData.getData('text/html')||e(plain).replace(/\r?\n/g,'<br>');document.execCommand('insertHTML',false,cleanRichText(html));});
document.addEventListener('error',ev=>{if(ev.target.tagName==='IMG'&&ev.target.closest('.presenter-photo')){ev.target.replaceWith(Object.assign(document.createElement('span'),{textContent:t('Photo unavailable','Fotografija nije dostupna')}));}},true);
render();
